import numpy as np
from scipy.optimize import least_squares
y=dP_dt
def mk(form):
    def f(p):
        a,b,c,d,e,g,h,k=p
        base=a+b*P+c/P+d*P**2
        if form=='exp': tt=t*P*(e+g*np.exp(-P/h))
        if form=='decay': tt=t*P*(e-g*P)+h*t*P*P*np.exp(-P/k)*0
        if form=='pow': tt=t*P*(e-g*P**h)
        if form=='rat': tt=t*P*(e+g*P)/(1+np.abs(h)*P**k)
        return base+tt
    return f
for form in ['exp','pow','rat']:
    best=None
    for s in range(20):
        p0=np.random.RandomState(s).uniform(0.2,1.5,8)
        try:
            r=least_squares(lambda p: mk(form)(p)-y, p0, max_nfev=3000)
        except Exception as ex: continue
        if best is None or r.cost<best.cost: best=r
